export declare const styles = "\n  :host {\n    \n  --_accent: var(--step-accent, #1d8049);\n  --_text: var(--step-text, #0d1310);\n  --_muted: var(--step-muted, #4a5650);\n  --_border: var(--step-border, #c3ccc6);\n  --_bg: var(--step-bg, #f6f8f6);\n\n    --_font: var(--step-font, inherit);\n    --_mono: var(--step-mono-font, ui-monospace, 'JetBrains Mono', Menlo, Consolas, monospace);\n    --_gap: var(--step-gap, 32px);\n    --_circle: var(--step-circle-size, 40px);\n    --_stagger: var(--step-stagger, 0.45s);\n    --_title-size: var(--step-title-size, 18px);\n    --_text-size: var(--step-text-size, 15px);\n    --_counter-size: var(--step-counter-size, clamp(3rem, 8vw, 6rem));\n    --_sticky-top: var(--step-sticky-top, 0px);\n    display: block;\n    container-type: inline-size;\n    color: var(--_text);\n    font-family: var(--_font);\n    line-height: 1.5;\n  }\n\n  :host([theme='dark']) {\n    \n  --_accent: var(--step-accent, #43c97e);\n  --_text: var(--step-text, #e9eeea);\n  --_muted: var(--step-muted, #a3ada6);\n  --_border: var(--step-border, #2c352f);\n  --_bg: var(--step-bg, #0b0e0c);\n\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :host(:not([theme='light'])) {\n      \n  --_accent: var(--step-accent, #43c97e);\n  --_text: var(--step-text, #e9eeea);\n  --_muted: var(--step-muted, #a3ada6);\n  --_border: var(--step-border, #2c352f);\n  --_bg: var(--step-bg, #0b0e0c);\n\n    }\n  }\n\n  :host([hidden]) {\n    display: none;\n  }\n\n  *,\n  *::before,\n  *::after {\n    box-sizing: border-box;\n  }\n\n  .steps {\n    display: grid;\n    grid-template-columns: repeat(var(--count), minmax(0, 1fr));\n    gap: var(--_gap);\n    margin: 0;\n    padding: 0;\n    list-style: none;\n  }\n\n  .step {\n    position: relative;\n    min-width: 0;\n  }\n\n  .number {\n    position: relative;\n    z-index: 1;\n    display: grid;\n    place-items: center;\n    width: var(--_circle);\n    height: var(--_circle);\n    margin-bottom: 20px;\n    border: 1px solid var(--_border);\n    border-radius: 50%;\n    background: var(--_bg);\n    color: var(--_muted);\n    font-family: var(--_mono);\n    font-size: 13px;\n    font-weight: 500;\n    line-height: 1;\n    transition:\n      color 0.3s ease,\n      border-color 0.3s ease;\n    transition-delay: calc(var(--i) * var(--_stagger));\n  }\n\n  .step:not(:last-child)::before,\n  .step:not(:last-child)::after {\n    content: '';\n    position: absolute;\n    top: calc(var(--_circle) / 2 - 1px);\n    left: var(--_circle);\n    right: calc(-1 * var(--_gap));\n    height: 2px;\n  }\n\n  .step:not(:last-child)::before {\n    background: var(--_border);\n  }\n\n  .step:not(:last-child)::after {\n    background: var(--_accent);\n    transform: scaleX(0);\n    transform-origin: left center;\n    transition: transform calc(var(--_stagger) - 0.1s) ease-in-out;\n    transition-delay: calc(var(--i) * var(--_stagger) + 0.1s);\n  }\n\n  .revealed .number {\n    border-color: var(--_accent);\n    color: var(--_accent);\n  }\n\n  .title {\n    margin: 0 0 6px;\n    color: var(--_text);\n    font-size: var(--_title-size);\n    font-weight: 600;\n    line-height: 1.3;\n  }\n\n  .text {\n    color: var(--_muted);\n    font-size: var(--_text-size);\n  }\n\n  .text > :first-child {\n    margin-top: 0;\n  }\n\n  .text > :last-child {\n    margin-bottom: 0;\n  }\n\n  @container (max-width: 639px) {\n    .steps {\n      grid-template-columns: minmax(0, 1fr);\n    }\n\n    .step {\n      padding-left: calc(var(--_circle) + 20px);\n      min-height: var(--_circle);\n    }\n\n    .number {\n      position: absolute;\n      top: 0;\n      left: 0;\n      margin: 0;\n    }\n\n    .title {\n      padding-top: calc((var(--_circle) - var(--_title-size) * 1.3) / 2);\n    }\n\n    .step:not(:last-child)::before,\n    .step:not(:last-child)::after {\n      top: var(--_circle);\n      right: auto;\n      bottom: calc(-1 * var(--_gap));\n      left: calc(var(--_circle) / 2 - 1px);\n      width: 2px;\n      height: auto;\n    }\n\n    .step:not(:last-child)::after {\n      transform: scaleY(0);\n      transform-origin: center top;\n    }\n  }\n\n  .steps.list {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .list .step {\n    padding-left: calc(var(--_circle) + 20px);\n    min-height: var(--_circle);\n  }\n\n  .list .number {\n    position: absolute;\n    top: 0;\n    left: 0;\n    margin: 0;\n  }\n\n  .list .title {\n    padding-top: calc((var(--_circle) - var(--_title-size) * 1.3) / 2);\n  }\n\n  .list .step:not(:last-child)::before,\n  .list .step:not(:last-child)::after {\n    top: var(--_circle);\n    right: auto;\n    bottom: calc(-1 * var(--_gap));\n    left: calc(var(--_circle) / 2 - 1px);\n    width: 2px;\n    height: auto;\n  }\n\n  .list .step:not(:last-child)::after {\n    transform: scaleY(0);\n    transform-origin: center top;\n  }\n\n  .list .step::after,\n  .list .number {\n    transition: none;\n  }\n\n  .revealed .step:not(:last-child)::after {\n    transform: none;\n  }\n\n  .pinned {\n    position: relative;\n    height: calc(var(--count) * var(--step-height));\n  }\n\n  .stage {\n    position: sticky;\n    top: var(--_sticky-top);\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr);\n    align-items: center;\n    gap: calc(var(--_gap) * 1.5);\n    height: calc(100svh - var(--_sticky-top));\n  }\n\n  .counter {\n    margin: 0;\n    font-family: var(--_mono);\n    font-size: var(--_counter-size);\n    font-weight: 500;\n    line-height: 1;\n    letter-spacing: -0.04em;\n    word-spacing: -0.4em;\n    font-variant-numeric: tabular-nums;\n    white-space: nowrap;\n  }\n\n  .total {\n    color: var(--_muted);\n    opacity: 0.6;\n  }\n\n  .bar {\n    position: relative;\n    height: 2px;\n    max-width: 280px;\n    margin-top: 28px;\n    background: var(--_border);\n    overflow: hidden;\n  }\n\n  .bar-fill {\n    position: absolute;\n    inset: 0;\n    background: var(--_accent);\n    transform: scaleX(0);\n    transform-origin: left center;\n  }\n\n  .active .title {\n    margin-bottom: 12px;\n    font-size: var(--step-active-title-size, clamp(1.5rem, 2.6vw, 2.25rem));\n    line-height: 1.2;\n    letter-spacing: -0.02em;\n  }\n\n  .active .text {\n    max-width: 46ch;\n    font-size: var(--step-active-text-size, 18px);\n  }\n\n  .visually-hidden {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    margin: -1px;\n    padding: 0;\n    overflow: hidden;\n    clip: rect(0 0 0 0);\n    white-space: nowrap;\n    border: 0;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .number,\n    .step::after {\n      transition: none !important;\n    }\n  }\n";
